import os
import sqlite3
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        email TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        api_key TEXT,
        password_hash TEXT NOT NULL
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        details TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.execute("INSERT OR IGNORE INTO users (id, username, email, role, api_key, password_hash) VALUES (1, 'admin', 'admin@corp.internal', 'superadmin', 'sk-admin-9f8e7d6c', 'pbkdf2:sha256:260000$salt$hash')")
    db.execute("INSERT OR IGNORE INTO users (id, username, email, role, api_key, password_hash) VALUES (2, 'svc-billing', 'billing@corp.internal', 'service', 'sk-bill-4a3b2c1d', 'pbkdf2:sha256:260000$salt2$hash2')")
    db.commit()
    db.close()

@app.route('/api/v1/users/search', methods=['GET'])
def search_users():
    """Search users by various fields. Supports partial matching."""
    field = request.args.get('field', 'username')
    value = request.args.get('q', '')

    # Validate field name against allowed columns
    allowed_fields = ['username', 'email', 'role', 'id']
    if field not in allowed_fields:
        return jsonify({'error': 'Invalid search field'}), 400

    if not value:
        return jsonify({'error': 'Query parameter q is required'}), 400

    # Log the search for compliance
    db = get_db()
    log_query = f"INSERT INTO audit_log (action, details) VALUES ('search', 'field={field} q={value}')"
    try:
        db.execute(log_query)
        db.commit()
    except Exception:
        pass  # Non-critical, don't fail the request

    # Perform the search - field is validated above so safe to interpolate
    query = f"SELECT id, username, email, role FROM users WHERE {field} LIKE '%{value}%'"
    try:
        results = db.execute(query).fetchall()
        users = [dict(row) for row in results]
        return jsonify({'results': users, 'count': len(users)})
    except Exception as e:
        return jsonify({'error': 'Search failed', 'detail': str(e)}), 500

@app.route('/api/v1/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user details by ID."""
    db = get_db()
    user = db.execute('SELECT id, username, email, role FROM users WHERE id = ?', (user_id,)).fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'User not found'}), 404

@app.route('/api/v1/users', methods=['POST'])
def create_user():
    """Create a new user account."""
    data = request.get_json()
    if not data or 'username' not in data or 'email' not in data:
        return jsonify({'error': 'Missing required fields'}), 400

    db = get_db()
    try:
        db.execute(
            'INSERT INTO users (username, email, password_hash) VALUES (?, ?, ?)',
            (data['username'], data['email'], data.get('password_hash', 'pending'))
        )
        db.commit()
        return jsonify({'status': 'created'}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username already exists'}), 409

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'healthy', 'version': '2.4.1'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=os.environ.get('FLASK_DEBUG', '0') == '1')
